// Characterization (golden master) tests: pin CURRENT behaviour of the orders API.
// Contract: test/orders-contract.yaml. Downstream pricing is replaced by an in-process fake.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 101, F: 100, G: 1 }
const fakePricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing: fakePricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('POST /orders creates an order with sequential string id, echoed items and total', async () => {
  const items = [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 45)
  const next = await (await post({ items })).json()
  assert.equal(Number(next.id), Number(order.id) + 1)
})

test('total at or below 100 gets no discount', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
})

test('total above 100 gets 10% off the whole amount', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — discount is a cliff: 101 -> 90 but 100 -> 100,
  // so a larger order can cost less than a smaller one (src/app.mjs: `if (total > 100)`).
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 90)   // 90.9 floored
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)  // 110 - 11
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalOf([{ sku: 'A', qty: 100 }]), 900)
})

test('discount is a flat 10% regardless of order size', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no tiers for larger orders; 10% at 101 and at 100000 alike.
  assert.equal(await totalOf([{ sku: 'A', qty: 10000 }]), 90000)
})

test('total is truncated with Math.floor, not rounded, and loses cents', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — total is a whole-euro integer, always rounded down.
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 33)   // 33.33
  assert.equal(await totalOf([{ sku: 'C', qty: 9 }]), 0)    // 0.9
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99)   // 99.99
})

test('line items are summed across skus before the discount', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }, { sku: 'G', qty: 1 }]), 90) // 101 -> 90.9
})

test('unvalidated input flows into the total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no validation of qty or unknown sku.
  assert.equal(await totalOf([{ sku: 'A', qty: -3 }]), -30)
  assert.equal(await totalOf([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await totalOf([{ sku: 'A', qty: 1.5 }]), 15)
  const res = await post({ items: [{ sku: 'UNKNOWN', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null) // NaN serialises as null
})

test('POST /orders rejects missing, empty, non-array items and bad JSON with 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await post(null, '{not json')
  assert.equal(bad.status, 400)
  assert.deepEqual(await bad.json(), { error: 'items required' })
  const empty = await post(null, '')
  assert.equal(empty.status, 400)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — missing order returns 200, not 404.
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods answer 404 no route', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    const res = await fetch(base + path, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
